---
import { defaultLang, type languages } from "../i18n/utils";

interface Props {
	title: string;
	description: string;
	lang?: keyof typeof languages;
	type?: "website" | "article";
	noindex?: boolean;
	schema?: Record<string, unknown>;
}

const {
	title,
	description,
	lang = defaultLang,
	type = "website",
	noindex = false,
	schema,
} = Astro.props;
const site = Astro.site ?? new URL("https://voxfusion.com");
const canonicalUrl = new URL(Astro.url.pathname, site).toString();
const imageUrl = new URL("/og.png?v=2026-05-15", site).toString();
const imageAlt = "VoxFusion local-first voice to text app for Mac";
const ogLocales: Partial<Record<string, string>> = {
	en: "en_US",
	ru: "ru_RU",
};
const locale = ogLocales[lang] ?? lang;
---

<meta name="description" content={description} />
{noindex && <meta name="robots" content="noindex, nofollow" />}
<link rel="canonical" href={canonicalUrl} />
<meta property="og:site_name" content="VoxFusion" />
<meta property="og:type" content={type} />
<meta property="og:title" content={title} />
<meta property="og:description" content={description} />
<meta property="og:url" content={canonicalUrl} />
<meta property="og:image" content={imageUrl} />
<meta property="og:image:secure_url" content={imageUrl} />
<meta property="og:image:type" content="image/png" />
<meta property="og:image:width" content="1200" />
<meta property="og:image:height" content="630" />
<meta property="og:image:alt" content={imageAlt} />
<meta property="og:locale" content={locale} />
<meta name="twitter:card" content="summary_large_image" />
<meta name="twitter:site" content="@voxfusion" />
<meta name="twitter:title" content={title} />
<meta name="twitter:description" content={description} />
<meta name="twitter:image" content={imageUrl} />
<meta name="twitter:image:alt" content={imageAlt} />
{schema && <script is:inline type="application/ld+json" set:html={JSON.stringify(schema)} />}

